document.addEventListener('DOMContentLoaded', () => {
  const projectFilter = document.getElementById('project-filter');
  const roomFilter = document.getElementById('room-filter');
  const sidebarProjectFilter = document.querySelector('.sidebar-project-filter');
  const sidebarRoomFilter = document.querySelector('.sidebar-room-filter');
  const galleryThumbnails = document.getElementById('gallery-thumbnails');
  const stickyPreviewImg = document.getElementById('sticky-preview-img');
  const previewCaption = document.getElementById('preview-caption');

  // Populate filter dropdowns
  portfolioProjects.forEach((project, index) => {
    const option = document.createElement('option');
    option.value = index.toString();
    option.textContent = project.title;

    if (projectFilter) projectFilter.appendChild(option.cloneNode(true));
    if (sidebarProjectFilter) sidebarProjectFilter.appendChild(option.cloneNode(true));
  });

  // Sync function
  function syncFilters(source, target) {
    if (!source || !target) return;
    target.value = source.value;
    renderThumbnails();
  }

  // Filter change event handlers (with syncing)
  if (projectFilter && sidebarProjectFilter) {
    projectFilter.addEventListener('change', () => syncFilters(projectFilter, sidebarProjectFilter));
    sidebarProjectFilter.addEventListener('change', () => syncFilters(sidebarProjectFilter, projectFilter));
  }
  if (roomFilter && sidebarRoomFilter) {
    roomFilter.addEventListener('change', () => syncFilters(roomFilter, sidebarRoomFilter));
    sidebarRoomFilter.addEventListener('change', () => syncFilters(sidebarRoomFilter, roomFilter));
  }

  // Initial render
  renderThumbnails();

  // Function to fix malformed asset paths from JSON extraction
  function cleanImagePath(path) {
    if (!path.startsWith('/')) {
      return '/' + path;
    }
    return path;
  }

  // ── iOS-Style Modal helpers (declared early so click handlers can reference them) ──
  const _modal = document.getElementById('gallery-modal');

  function openModal() {
    if (!_modal) return;
    _modal.style.display = 'flex';
    _modal.getBoundingClientRect(); // force reflow
    _modal.classList.add('is-modal-open');
    document.body.style.overflow = 'hidden';
  }

  function closeModal() {
    if (!_modal) return;
    _modal.classList.remove('is-modal-open');
    _modal.classList.add('is-closing');
    document.body.style.overflow = '';
    setTimeout(() => {
      _modal.classList.remove('is-closing');
      _modal.style.display = '';
      if (stickyPreviewImg) {
        stickyPreviewImg.style.transform = '';
        stickyPreviewImg.style.opacity = '';
      }
      _modal.style.background = '';
    }, 320);
  }

  // Generate thumbnail grid
  function renderThumbnails() {
    const projectValue = projectFilter ? projectFilter.value : 'all';
    const roomValue = roomFilter ? roomFilter.value : 'all';

    galleryThumbnails.innerHTML = '';
    let firstImageToLoad = null;
    let firstCaption = '';

    portfolioProjects.forEach((project, pIndex) => {
      // If a specific project is selected, skip others
      if (projectValue !== 'all' && pIndex.toString() !== projectValue) return;

      project.images.forEach((imgPath, imgIndex) => {
        const cleanedPath = cleanImagePath(imgPath);
        const roomType = galleryTags[cleanedPath] || 'Others';

        // If a specific room type is selected, skip others
        if (roomValue !== 'all' && roomType !== roomValue) return;

        const caption = `${project.title} - ${roomType} - ${imgIndex + 1}`;

        // Save first image to auto-load into preview
        if (!firstImageToLoad) {
          firstImageToLoad = cleanedPath;
          firstCaption = caption;
        }

        const button = document.createElement('button');
        button.className = 'w-full aspect-square overflow-hidden rounded-lg group focus:outline-none focus:ring-2 focus:ring-lux-gold bg-lux-dark/10';
        button.innerHTML = `
          <img 
            src="${cleanedPath}" 
            alt="${caption}" 
            class="w-full h-full object-cover transition-transform duration-500 group-hover:scale-105"
            loading="lazy"
          />
        `;

        button.addEventListener('click', () => {
          updateStickyPreview(cleanedPath, caption);
          if (window.innerWidth < 1080) {
            openModal();
          }
        });

        galleryThumbnails.appendChild(button);
      });
    });

    if (firstImageToLoad && stickyPreviewImg) {
      updateStickyPreview(firstImageToLoad, firstCaption);
    } else if (!firstImageToLoad) {
      // No images found for this combination
      galleryThumbnails.innerHTML = '<div class="col-span-full py-20 text-center text-lux-dark/40 font-medium italic">No images found for this filter combination.</div>';
    }
  }

  // Update preview image
  function updateStickyPreview(src, alt) {
    stickyPreviewImg.style.opacity = '0';
    setTimeout(() => {
      stickyPreviewImg.src = src;
      stickyPreviewImg.alt = alt;
      if (previewCaption) previewCaption.textContent = alt;
      stickyPreviewImg.style.opacity = '1';
    }, 200); // Small transition delay
  }

  // Filter change event handler
  if (projectFilter) {
    projectFilter.addEventListener('change', () => {
      renderThumbnails();
    });
  }

  if (roomFilter) {
    roomFilter.addEventListener('change', () => {
      renderThumbnails();
    });
  }

  // ── iOS-Style Modal: Button & Backdrop listeners ──────────────────────
  const closeBtn = document.getElementById('modal-close-btn');

  if (closeBtn) {
    closeBtn.addEventListener('click', closeModal);
  }

  if (_modal) {
    // Close on backdrop tap
    _modal.addEventListener('click', (e) => {
      if (window.innerWidth < 1080 && e.target === _modal) {
        closeModal();
      }
    });
  }

  // ── Swipe-to-Dismiss Touch Gesture ────────────────────────────────────
  if (_modal && stickyPreviewImg) {
    let touchStartY = 0;
    let touchStartX = 0;
    let currentDeltaY = 0;
    let isDragging = false;
    const DISMISS_THRESHOLD = 100; // px swipe down to dismiss

    _modal.addEventListener('touchstart', (e) => {
      if (window.innerWidth >= 1080) return;
      touchStartY = e.touches[0].clientY;
      touchStartX = e.touches[0].clientX;
      isDragging = false;
    }, { passive: true });

    _modal.addEventListener('touchmove', (e) => {
      if (window.innerWidth >= 1080) return;
      const deltaY = e.touches[0].clientY - touchStartY;
      const deltaX = e.touches[0].clientX - touchStartX;

      // Only activate swipe-down if motion is more vertical than horizontal
      if (!isDragging && Math.abs(deltaY) > Math.abs(deltaX) && deltaY > 6) {
        isDragging = true;
        _modal.classList.add('is-dragging');
      }

      if (!isDragging) return;
      e.preventDefault();

      currentDeltaY = Math.max(0, deltaY);
      const progress = Math.min(currentDeltaY / DISMISS_THRESHOLD, 1);
      const scale = 1 - progress * 0.18;
      const backdropOpacity = 0.96 - progress * 0.96;

      stickyPreviewImg.style.transform = `translateY(${currentDeltaY}px) scale(${scale})`;
      _modal.style.background = `rgba(10, 10, 10, ${backdropOpacity})`;
    }, { passive: false });

    _modal.addEventListener('touchend', () => {
      if (window.innerWidth >= 1080 || !isDragging) return;
      _modal.classList.remove('is-dragging');
      isDragging = false;

      if (currentDeltaY >= DISMISS_THRESHOLD) {
        closeModal();
      } else {
        // Snap back to open position
        stickyPreviewImg.style.transition = 'transform 0.35s cubic-bezier(0.32, 0.72, 0, 1)';
        stickyPreviewImg.style.transform = 'scale(1) translateY(0)';
        _modal.style.background = 'rgba(10, 10, 10, 0.96)';
        setTimeout(() => { stickyPreviewImg.style.transition = ''; }, 360);
      }
      currentDeltaY = 0;
    }, { passive: true });
  }

  // Initial render
  renderThumbnails('all');
});
